// 금융위원회 보도자료 목록에서 당일 등록건 추출
const html = $input.first().json.data;
const now = new Date();
const koreaTime = new Date(now.getTime() + (9 * 60 * 60 * 1000));
const year = koreaTime.getFullYear();
const month = String(koreaTime.getMonth() + 1).padStart(2, '0');
const day = String(koreaTime.getDate()).padStart(2, '0');
const todayStr = `${year}.${month}.${day}`;
const todayDash = `${year}-${month}-${day}`;

const items = [];

// FSC 사이트의 게시물 목록 파싱
// 테이블 행 단위로 처리
const rowPattern = /<tr[^>]*>(.*?)<\/tr>/gs;
let match;
while ((match = rowPattern.exec(html)) !== null) {
  const row = match[1];
  // 당일 날짜가 포함된 행만
  if (row.includes(todayStr) || row.includes(todayDash)) {
    const idMatch = /noticeId=(\d+)/.exec(row);
    const titleMatch = /<a[^>]*>(.*?)<\/a>/s.exec(row);
    if (idMatch && titleMatch) {
      items.push({
        json: {
          noticeId: idMatch[1],
          title: titleMatch[1].replace(/<[^>]*>/g, '').trim(),
          date: todayDash,
          url: `https://www.fsc.go.kr/no010101/view?noticeId=${idMatch[1]}`,
          source: '금융위원회',
          type: 'government_policy'
        }
      });
    }
  }
}

// 목록 형태가 다를 수 있으므로 li/div 패턴도 시도
if (items.length === 0) {
  const listPattern = /<a[^>]*href="[^"]*noticeId=(\d+)"[^>]*>(.*?)<\/a>/gs;
  const dateCheckPattern = new RegExp(`(${todayStr}|${todayDash})`);
  // 전체 HTML을 섹션으로 나누어 날짜 체크
  const sections = html.split(/<\/li>|<\/tr>/);
  for (const section of sections) {
    if (dateCheckPattern.test(section)) {
      const linkMatch = /noticeId=(\d+)/.exec(section);
      const textMatch = /<a[^>]*>(.*?)<\/a>/s.exec(section);
      if (linkMatch && textMatch) {
        const title = textMatch[1].replace(/<[^>]*>/g, '').trim();
        if (title && !items.find(i => i.json.noticeId === linkMatch[1])) {
          items.push({
            json: {
              noticeId: linkMatch[1],
              title: title,
              date: todayDash,
              url: `https://www.fsc.go.kr/no010101/view?noticeId=${linkMatch[1]}`,
              source: '금융위원회',
              type: 'government_policy'
            }
          });
        }
      }
    }
  }
}

if (items.length === 0) {
  return [{ json: { noData: true, type: 'government_policy', message: '오늘 등록된 금융위 보도자료 없음' } }];
}

return items;

// 상세 페이지에서 PDF 첨부파일 URL 추출 및 본문 요약
const html = $input.first().json.data || '';
const prevData = $('FSC 데이터 존재?').first().json;

// PDF 링크 추출
const pdfLinks = [];
// href에 .pdf가 포함된 링크
const pdfPattern = /href="([^"]*\.pdf[^"]*)"/gi;
let m;
while ((m = pdfPattern.exec(html)) !== null) {
  let url = m[1];
  if (!url.startsWith('http')) url = 'https://www.fsc.go.kr' + url;
  pdfLinks.push(url);
}
// 파일 다운로드 패턴
const dlPattern = /\/cmm\/fms\/FileDown\.do\?[^"'\s]*/gi;
while ((m = dlPattern.exec(html)) !== null) {
  pdfLinks.push('https://www.fsc.go.kr' + m[0]);
}
// atchFileId 패턴
const atchPattern = /fn_egov_downFile\(['"]([^'"]+)['"]\s*,\s*['"]([^'"]+)['"]\)/gi;
while ((m = atchPattern.exec(html)) !== null) {
  pdfLinks.push(`https://www.fsc.go.kr/cmm/fms/FileDown.do?atchFileId=${m[1]}&fileSn=${m[2]}`);
}

// 본문 내용 추출
let content = '';
const contentPatterns = [
  /<div[^>]*class="[^"]*view[_-]?con[^"]*"[^>]*>(.*?)<\/div>/s,
  /<div[^>]*class="[^"]*board[_-]?con[^"]*"[^>]*>(.*?)<\/div>/s,
  /<td[^>]*class="[^"]*content[^"]*"[^>]*>(.*?)<\/td>/s
];
for (const pat of contentPatterns) {
  const cm = pat.exec(html);
  if (cm) {
    content = cm[1].replace(/<[^>]*>/g, ' ').replace(/\s+/g, ' ').trim();
    break;
  }
}
if (content.length > 500) content = content.substring(0, 500) + '...';

return [{
  json: {
    noticeId: prevData.noticeId,
    title: prevData.title,
    date: prevData.date,
    url: prevData.url,
    source: '금융위원회',
    type: 'government_policy',
    content: content,
    pdfUrls: [...new Set(pdfLinks)],
    pdfCount: [...new Set(pdfLinks)].length
  }
}];

// PDF URL을 개별 아이템으로 분리
const item = $input.first().json;
return item.pdfUrls.map((url, i) => ({
  json: {
    ...item,
    pdfUrl: url,
    pdfIndex: i + 1,
    fileName: `FSC_${item.date}_${item.noticeId}_${i+1}.pdf`
  }
}));

// 구글시트 정부정책 시트에 데이터 추가 (API 직접 호출)
const spreadsheetId = '1udyrgfZvGZtCOett-ZrUG_hgwser38BIMhRo_Kq8ZSA';
const sheetName = '정부정책';
const items = $input.all();

const validItems = items.filter(i => !i.json.noData && i.json.title);
if (validItems.length === 0) {
  return items;
}

const now = new Date().toISOString().replace('T', ' ').substring(0, 19);
const rows = validItems.map(item => [
  item.json.date || '',
  item.json.title || '',
  item.json.summary || '',
  item.json.link || '',
  String(item.json.pdfCount || 0),
  'N',
  now
]);

try {
  await this.helpers.httpRequestWithAuthentication.call(
    this,
    'googleSheetsOAuth2Api',
    {
      method: 'POST',
      url: `https://sheets.googleapis.com/v4/spreadsheets/${spreadsheetId}/values/${encodeURIComponent(sheetName)}:append?valueInputOption=RAW&insertDataOption=INSERT_ROWS`,
      body: { values: rows },
      json: true
    }
  );
  console.log('정부정책 저장 완료:', rows.length, '건');
} catch (error) {
  console.log('정부정책 저장 실패:', error.message);
}

return items;

// 구글시트에서 정부정책 발송내역 조회 (API 직접 호출)
const spreadsheetId = '1udyrgfZvGZtCOett-ZrUG_hgwser38BIMhRo_Kq8ZSA';
const sheetName = '정부정책_발송내역';

try {
  const response = await this.helpers.httpRequestWithAuthentication.call(
    this,
    'googleSheetsOAuth2Api',
    {
      method: 'GET',
      url: `https://sheets.googleapis.com/v4/spreadsheets/${spreadsheetId}/values/${encodeURIComponent(sheetName)}`,
      json: true
    }
  );

  const rows = response.values || [];
  if (rows.length <= 1) {
    return [{ json: { noData: true, message: '발송내역 없음' } }];
  }

  const headers = rows[0];
  const results = [];
  for (let i = 1; i < rows.length; i++) {
    const obj = {};
    headers.forEach((h, j) => { obj[h] = rows[i][j] || ''; });
    results.push({ json: obj });
  }

  console.log('정부정책 발송내역:', results.length, '건 조회');
  return results;
} catch (error) {
  console.log('정부정책 발송내역 조회 실패:', error.message);
  return [{ json: { noData: true, message: '조회 실패: ' + error.message } }];
}

// 이미 발송된 정책 제외 (중복 발송 방지)
const savedPolicies = $('구글시트 정부정책 저장').all();
const sentHistory = $('정부정책 발송내역 조회').all();

const sentTitles = new Set();
for (const item of sentHistory) {
  if (item.json.제목) sentTitles.add(item.json.제목.trim());
}

const newPolicies = [];
for (const item of savedPolicies) {
  const title = (item.json.title || item.json.제목 || '').trim();
  if (title && !sentTitles.has(title)) {
    newPolicies.push({
      json: {
        title: title,
        content: item.json.content || item.json.내용요약 || '',
        url: item.json.url || item.json.원문링크 || '',
        date: item.json.date || item.json.날짜 || '',
        pdfCount: item.json.pdfCount || item.json.PDF파일수 || 0,
        source: '금융위원회',
        type: 'government_policy'
      }
    });
  }
}

if (newPolicies.length === 0) {
  return [{ json: { noData: true, type: 'government_policy', policies: [], count: 0 } }];
}

return [{ json: { type: 'government_policy', policies: newPolicies.map(p => p.json), count: newPolicies.length } }];

// 네이버 뉴스 수집 기간 설정: 전날 06:30 ~ 당일 06:30
const now = new Date();
const koreaTime = new Date(now.getTime() + (9 * 60 * 60 * 1000));

// 당일 06:30 KST
const endTime = new Date(koreaTime);
endTime.setHours(6, 30, 0, 0);

// 전날 06:30 KST
const startTime = new Date(endTime);
startTime.setDate(startTime.getDate() - 1);

// 검색 키워드 목록
const keywords = ['펀드', '공모펀드', 'ETF 자산운용', '금융투자 펀드'];

return keywords.map(kw => ({
  json: {
    keyword: kw,
    startTime: startTime.toISOString(),
    endTime: endTime.toISOString(),
    startDateStr: startTime.toISOString().split('T')[0],
    endDateStr: endTime.toISOString().split('T')[0]
  }
}));

// 네이버 뉴스 수집 및 파싱 (API 호출 + 시간 필터링 + HTML 정리)
const items = $input.all();
const allNews = [];
const seenUrls = new Set();

for (const item of items) {
  const keyword = item.json.keyword;
  const startTime = new Date(item.json.startTime);
  const endTime = new Date(item.json.endTime);

  try {
    const response = await this.helpers.httpRequest({
      method: 'GET',
      url: 'https://openapi.naver.com/v1/search/news.json',
      qs: {
        query: keyword,
        display: 50,
        sort: 'date'
      },
      headers: {
        'X-Naver-Client-Id': process.env.NAVER_CLIENT_ID || 'YOUR_NAVER_CLIENT_ID',
        'X-Naver-Client-Secret': process.env.NAVER_CLIENT_SECRET || 'YOUR_NAVER_CLIENT_SECRET'
      }
    });

    const newsItems = response.items || [];
    console.log(`키워드 "${keyword}": ${newsItems.length}건 수신`);

    for (const news of newsItems) {
      const pubDate = new Date(news.pubDate);

      // 시간 범위 필터 (전날 06:30 ~ 당일 06:30)
      if (pubDate >= startTime && pubDate <= endTime) {
        // HTML 태그 및 엔티티 정리
        const cleanTitle = (news.title || '')
          .replace(/<[^>]*>/g, '')
          .replace(/&quot;/g, '"')
          .replace(/&amp;/g, '&')
          .replace(/&lt;/g, '<')
          .replace(/&gt;/g, '>')
          .replace(/&apos;/g, "'")
          .replace(/&#\d+;/g, '');
        const cleanDesc = (news.description || '')
          .replace(/<[^>]*>/g, '')
          .replace(/&quot;/g, '"')
          .replace(/&amp;/g, '&')
          .replace(/&lt;/g, '<')
          .replace(/&gt;/g, '>')
          .replace(/&apos;/g, "'")
          .replace(/&#\d+;/g, '');
        const url = news.originallink || news.link;

        if (!seenUrls.has(url)) {
          seenUrls.add(url);
          allNews.push({
            json: {
              title: cleanTitle,
              description: cleanDesc,
              link: url,
              originallink: news.originallink || '',
              pubDate: news.pubDate,
              source: '네이버뉴스',
              keyword: keyword
            }
          });
        }
      }
    }
  } catch (error) {
    console.log(`키워드 "${keyword}" API 호출 실패: ${error.message}`);
  }
}

// 최신순 정렬
allNews.sort((a, b) => new Date(b.json.pubDate) - new Date(a.json.pubDate));

console.log(`총 ${allNews.length}건 수집 (시간필터링 + URL 중복제거 완료)`);

if (allNews.length === 0) {
  return [{ json: { title: '', link: '', source: 'naver_empty', noData: true } }];
}

return allNews;

// 구글시트 네이버뉴스_수집 시트에 데이터 추가 (API 직접 호출)
const spreadsheetId = '1udyrgfZvGZtCOett-ZrUG_hgwser38BIMhRo_Kq8ZSA';
const sheetName = '네이버뉴스_수집';
const items = $input.all();

// noData인 경우 스킵
const validItems = items.filter(i => !i.json.noData && i.json.title);
if (validItems.length === 0) {
  return items; // 원본 그대로 전달
}

const now = new Date().toISOString().replace('T', ' ').substring(0, 19);
const rows = validItems.map(item => [
  item.json.title || '',
  item.json.link || '',
  item.json.pubDate || '',
  now
]);

try {
  await this.helpers.httpRequestWithAuthentication.call(
    this,
    'googleSheetsOAuth2Api',
    {
      method: 'POST',
      url: `https://sheets.googleapis.com/v4/spreadsheets/${spreadsheetId}/values/${encodeURIComponent(sheetName)}:append?valueInputOption=RAW&insertDataOption=INSERT_ROWS`,
      body: { values: rows },
      json: true
    }
  );
  console.log('네이버뉴스 저장 완료:', rows.length, '건');
} catch (error) {
  console.log('네이버뉴스 저장 실패:', error.message);
}

return items; // 원본 데이터 그대로 다음 노드로 전달

// 구글시트에서 과거 수집뉴스 조회 (API 직접 호출)
const spreadsheetId = '1udyrgfZvGZtCOett-ZrUG_hgwser38BIMhRo_Kq8ZSA';
const sheetName = '네이버뉴스_수집';

try {
  const response = await this.helpers.httpRequestWithAuthentication.call(
    this,
    'googleSheetsOAuth2Api',
    {
      method: 'GET',
      url: `https://sheets.googleapis.com/v4/spreadsheets/${spreadsheetId}/values/${encodeURIComponent(sheetName)}`,
      json: true
    }
  );

  const rows = response.values || [];
  if (rows.length <= 1) {
    return [{ json: { noData: true, message: '과거 수집뉴스 없음' } }];
  }

  const headers = rows[0];
  const results = [];
  for (let i = 1; i < rows.length; i++) {
    const obj = {};
    headers.forEach((h, j) => { obj[h] = rows[i][j] || ''; });
    results.push({ json: obj });
  }

  console.log('과거 수집뉴스:', results.length, '건 조회');
  return results;
} catch (error) {
  console.log('과거 수집뉴스 조회 실패:', error.message);
  return [{ json: { noData: true, message: '조회 실패: ' + error.message } }];
}

// 키워드 필터링 + 당일 수집 내 중복 제거 (과거 이력 중복은 전체 데이터 통합에서 처리)
// 연결된 모든 입력(뉴스 병합 + 구글시트 네이버뉴스 저장)을 $input.all()로 수신
const allItems = $input.all();

// 관심 키워드
const includeKeywords = [
  '펀드', '투자신탁', 'ETF', '자산운용', '공모',
  'ISA', 'IRP', '연금저축', '퇴직연금',
  '비과세', '세제', '조세', '과세', '면세', '감면',
  '금융투자', '증권', '자본시장', '금융소비자',
  '금융위', '금감원'
];

// 제외 키워드
const excludeKeywords = [
  '인사', '승진', '임명', '취임', '전보', '이임',
  '채용', '모집', '공모전', '시험', '광고'
];

const filtered = [];
for (const item of allItems) {
  const title = item.json.title || '';
  if (!title || item.json.noData) continue;

  const hasExclude = excludeKeywords.some(kw => title.includes(kw));
  if (hasExclude) continue;

  const hasInclude = includeKeywords.some(kw => title.includes(kw));
  if (hasInclude) {
    filtered.push({
      json: {
        title: title,
        link: item.json.link || item.json.url || item.json.originallink || '',
        pubDate: item.json.pubDate || item.json.isoDate || '',
        source: item.json.source || '기타',
        type: 'news'
      }
    });
  }
}

// 당일 수집 내 제목 기준 중복 제거
const normalize = (t) => t.toLowerCase().replace(/[\s\W]/g, '');
const seen = new Set();
const unique = filtered.filter(item => {
  const key = normalize(item.json.title);
  if (seen.has(key)) return false;
  for (const s of seen) {
    if (key.length > 10 && s.length > 10) {
      if (key.includes(s) || s.includes(key)) return false;
    }
  }
  seen.add(key);
  return true;
});

return unique.slice(0, 15);

// KOFIA 신규펀드 조회 - 지난주 월~일 기간 설정
const now = new Date();
const koreaTime = new Date(now.getTime() + (9 * 60 * 60 * 1000));
const dayOfWeek = koreaTime.getDay(); // 0=일, 1=월, ...

// 지난주 월요일 계산
// dayOfWeek=0(일)이면 -13, dayOfWeek=1(월)이면 -7, dayOfWeek=2(화)이면 -8, ...
const daysToLastMonday = dayOfWeek === 0 ? 13 : dayOfWeek + 6;
const lastMonday = new Date(koreaTime);
lastMonday.setDate(koreaTime.getDate() - daysToLastMonday);
lastMonday.setHours(0, 0, 0, 0);

// 지난주 일요일
const lastSunday = new Date(lastMonday);
lastSunday.setDate(lastMonday.getDate() + 6);
lastSunday.setHours(23, 59, 59, 999);

const formatDate = (d) => {
  const y = d.getFullYear();
  const m = String(d.getMonth() + 1).padStart(2, '0');
  const dd = String(d.getDate()).padStart(2, '0');
  return `${y}${m}${dd}`;
};

const formatDateDash = (d) => {
  const y = d.getFullYear();
  const m = String(d.getMonth() + 1).padStart(2, '0');
  const dd = String(d.getDate()).padStart(2, '0');
  return `${y}-${m}-${dd}`;
};

console.log('조회기간:', formatDateDash(lastMonday), '~', formatDateDash(lastSunday));

return [{
  json: {
    startDate: formatDate(lastMonday),
    endDate: formatDate(lastSunday),
    startDateDash: formatDateDash(lastMonday),
    endDateDash: formatDateDash(lastSunday),
    fundGubun: '1',  // 1=공모펀드
    type: 'new_fund'
  }
}];

// KOFIA 신규펀드 조회 API 호출 (ProFrame XML format)
const input = $input.first().json;

const xmlBody = '<?xml version="1.0" encoding="utf-8"?>' +
  '<message>' +
  '<proframeHeader>' +
  '<pfmAppName>FS-DIS2</pfmAppName>' +
  '<pfmSvcName>DISNewEstSO</pfmSvcName>' +
  '<pfmFnName>select</pfmFnName>' +
  '</proframeHeader>' +
  '<systemHeader></systemHeader>' +
  '<DISCondFuncDTO>' +
  '<tmpV30>' + input.startDate + '</tmpV30>' +
  '<tmpV31>' + input.endDate + '</tmpV31>' +
  '<tmpV12></tmpV12>' +
  '<tmpV3></tmpV3>' +
  '<tmpV5></tmpV5>' +
  '<tmpV4></tmpV4>' +
  '<tmpV7>' + input.fundGubun + '</tmpV7>' +
  '</DISCondFuncDTO>' +
  '</message>';

try {
  const response = await this.helpers.httpRequest({
    method: 'POST',
    url: 'https://dis.kofia.or.kr/proframeWeb/XMLSERVICES/',
    headers: {
      'Content-Type': 'text/xml; charset=UTF-8',
      'Referer': 'https://dis.kofia.or.kr/websquare/index.jsp?w2xPath=/wq/fundann/DISNewEst.xml'
    },
    body: xmlBody,
    returnFullResponse: false,
    encoding: 'utf-8'
  });

  let responseText = '';
  if (typeof response === 'string') {
    responseText = response;
  } else if (response && response.data) {
    responseText = typeof response.data === 'string' ? response.data : JSON.stringify(response.data);
  } else {
    try { responseText = JSON.stringify(response); } catch(e) { responseText = String(response); }
  }

  return [{ json: { data: responseText, startDate: input.startDate, endDate: input.endDate } }];
} catch (error) {
  return [{ json: { noData: true, type: 'new_fund', message: 'KOFIA API 호출 실패: ' + error.message } }];
}

// KOFIA ProFrame XML 응답 파싱 - 신규펀드 정보 추출
// 응답 구조: <selectMeta> 안에 동일한 tmpV 태그가 레코드 수만큼 반복
const responseData = $input.first().json.data || $input.first().json;
let xml = '';

if (typeof responseData === 'string') {
  xml = responseData;
} else if (responseData.data) {
  xml = responseData.data;
} else {
  xml = JSON.stringify(responseData);
}

const funds = [];

// ProFrame 응답에서 에러 체크
if (xml.includes('COMS9009') || xml.includes('MODULE ERROR')) {
  console.log('KOFIA API 에러:', xml.substring(0, 500));
  return [{ json: { noData: true, type: 'new_fund', message: 'KOFIA API 서비스 오류' } }];
}

// selectMeta 안에서 tmpV1(운용사)을 기준으로 레코드 분리
// tmpV1=운용사, tmpV2=펀드명, tmpV3=설정일, tmpV4=유형, tmpV5=투자지역
// tmpV8=수탁사, tmpV9=사무수탁사, tmpV10=표준코드
const v1Regex = /<tmpV1>([^<]*)<\/tmpV1>/g;
const v1Matches = [];
let m;
while ((m = v1Regex.exec(xml)) !== null) {
  v1Matches.push({ value: m[1], index: m.index });
}

for (let i = 0; i < v1Matches.length; i++) {
  const start = v1Matches[i].index;
  const end = i + 1 < v1Matches.length ? v1Matches[i + 1].index : xml.indexOf('</selectMeta>');
  const chunk = xml.substring(start, end);

  const getValue = (tag) => {
    const match = new RegExp('<' + tag + '>([^<]*)</' + tag + '>').exec(chunk);
    return match ? match[1].trim() : '';
  };

  const company = getValue('tmpV1');
  const fundName = getValue('tmpV2');
  const setupDate = getValue('tmpV3');
  const fundType = getValue('tmpV4');
  const investRegion = getValue('tmpV5');
  const trustee = getValue('tmpV8');
  const stdCode = getValue('tmpV10');

  if (fundName) {
    funds.push({ company, fundName, setupDate, fundType, investRegion, stdCode, trustee });
  }
}

console.log('KOFIA 응답 파싱: 총', funds.length, '건의 펀드');

if (funds.length === 0) {
  return [{ json: { noData: true, type: 'new_fund', message: '지난주 신규 공모펀드 없음' } }];
}

