  return name
    .replace(/\s*\([^)]*\)\s*/g, '')
    .replace(/\s*Class\s*[A-Z].*$/i, '')
    .replace(/\s*_\s*C[-\w]*$/i, '')
    .replace(/\s*(A|B|C|C-e|C-P|C-P2|C-P2e|C-F|C-W|D|E|F|G|I|S|W|P|CP|CE|Cf|Cpe)\s*$/i, '')
    .replace(/제?\d+호$/g, '')
    .trim();
};

const checkFundSupermarket = (name) => {
  const n = name || '';
  return /[_\s]S($|[\[\(])/i.test(n) || /[_\s]S-[RPFe]/i.test(n) || /Class\s*S/i.test(n);
};

const seenFunds = new Map();
for (const fund of funds) {
  const key = normalizeName(fund.fundName) + '_' + fund.company;
  const isFSM = checkFundSupermarket(fund.fundName);
  if (!seenFunds.has(key)) {
