}));

// Claude AI에 투자전략 분석 요청
const fundListText = fundData.map(f =>
  `${f.no}. [${f.company}] ${f.fundName} | 유형: ${f.fundType} | 투자지역: ${f.investRegion}`
).join('\n');

const aiPrompt = `너는 한국 자산운용업계 펀드 전문가야. 아래 신규 출시 공모펀드들의 간이투자설명서를 분석한 전문가처럼, 각 펀드의 투자전략을 25자 이내로 요약해줘.

펀드명, 운용사, 유형 등에서 투자 전략의 핵심을 파악해서 간결하게 작성해.

펀드 목록:
${fundListText}

응답 형식 (반드시 번호만 사용, 설명 없이):
